const fs = require('fs'); const {PNG}=require('pngjs'); const pixelmatch=require('pixelmatch');
const ref=PNG.sync.read(fs.readFileSync('e2e/home-v2/fixtures/navbar-reference.png')), act=PNG.sync.read(fs.readFileSync('e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'));
const boxes=[[494,24,38,34],[634,24,38,34],[750,24,38,34],[871,24,38,34],[997,24,38,34],[1127,24,38,34],[1256,24,38,34],[1385,24,38,34],[1516,24,38,34],[1640,24,38,34],[1688,38,28,34],[1855,22,36,36]];
function score(x0,y0,w,h,excludeIcons=false){const a=Buffer.alloc(w*h*4),b=Buffer.alloc(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const sx=x+x0,sy=y+y0,si=(sy*ref.width+sx)*4,di=(y*w+x)*4;let masked=false;if(excludeIcons)for(const [bx,by,bw,bh] of boxes)if(sx>=bx&&sx<bx+bw&&sy>=by&&sy<by+bh){masked=true;break;}if(!masked){ref.data.copy(a,di,si,si+4);act.data.copy(b,di,si,si+4);}}const diff=pixelmatch(a,b,Buffer.alloc(w*h*4),w,h,{threshold:0.1,includeAA:false});let compared=w*h;if(excludeIcons){for(let y=0;y<h;y++)for(let x=0;x<w;x++){const sx=x+x0,sy=y+y0;for(const [bx,by,bw,bh] of boxes)if(sx>=bx&&sx<bx+bw&&sy>=by&&sy<by+bh){compared--;break;}}}return +((1-diff/compared)*100).toFixed(3);}
const regions={brand:[0,0,430,110],navigation:[430,0,1250,110],right:[1680,0,240,110],topBand:[0,0,1920,20],skylineBand:[0,20,1920,72],bottomBand:[0,92,1920,18],menuLabels:[430,64,1250,26],brandTitle:[65,28,320,52],activeCard:[430,18,160,76]};
const out={};for(const [name,[x,y,w,h]] of Object.entries(regions))out[name]={all:score(x,y,w,h),withoutIcons:score(x,y,w,h,true)};console.log(JSON.stringify(out,null,2));
'@; node -e $pixelScript
